/**
 * Cartesia keyterms (§6, §8): generated by A's grammar (`keyterms()`, from actions.ts voice phrases
 * + EXTRA_KEYTERMS; aliases excluded). Cartesia's limits are ≤ 100 terms and ≤ 1200 characters in
 * total; keyterms are immutable per connection. This wrapper enforces the limits defensively
 * (dedupe, drop empties, never exceed either cap) so a growing action table can never break the
 * socket handshake.
 */
import { keyterms as grammarKeyterms } from "../pipeline/grammar";

export const KEYTERM_MAX_COUNT = 100;
export const KEYTERM_MAX_CHARS = 1200;

export function limitKeyterms(terms: string[]): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  let chars = 0;
  for (const raw of terms) {
    const t = raw.trim();
    if (!t || seen.has(t)) continue;
    if (out.length >= KEYTERM_MAX_COUNT) break;
    if (chars + t.length > KEYTERM_MAX_CHARS) continue;
    seen.add(t);
    out.push(t);
    chars += t.length;
  }
  return out;
}

export function sttKeyterms(source: () => string[] = grammarKeyterms): string[] {
  return limitKeyterms(source());
}
